import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateRbacRolesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateRbacRolesWorkflow(req.scope)
    .run({
      input: {
        "selector": "{value}",
        "update": {
          "update": "{value}"
        }
      }
    })

  res.send(result)
}

